"""Command-line interface for pennywise."""

import argparse
import csv
import json
import os
import sys
from typing import List, Optional

from .ledger import (
    Entry,
    ParseError,
    balance,
    by_category,
    by_month,
    filter_entries,
    format_amount,
    format_entry,
    parse,
    parse_date,
    parse_line,
)

EXIT_OK = 0
EXIT_LEDGER = 1
EXIT_USAGE = 2


class _ReadError(Exception):
    pass


def _date_arg(text: str):
    try:
        return parse_date(text)
    except ValueError as exc:
        raise argparse.ArgumentTypeError(str(exc)) from None


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        prog="pennywise", description="Tell where the money in a plain-text ledger went."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    def file_arg(p):
        p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")

    p = sub.add_parser("balance", help="print the total of all entries")
    file_arg(p)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("summary", help="print totals per category or month")
    file_arg(p)
    p.add_argument("--by", choices=["category", "month"], default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("list", help="print matching entries, oldest first")
    file_arg(p)
    p.add_argument("--category", metavar="C")
    p.add_argument("--since", metavar="DATE", type=_date_arg)
    p.add_argument("--until", metavar="DATE", type=_date_arg)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = sub.add_parser("add", help="append an entry to the ledger")
    p.add_argument("file", metavar="FILE")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = sub.add_parser("export", help="print entries as CSV")
    file_arg(p)
    p.add_argument("--format", choices=["csv"], default="csv")

    return parser


def _decode(data: bytes, name: str) -> str:
    try:
        return data.decode("utf-8-sig")
    except UnicodeDecodeError as exc:
        raise _ReadError(f"{name}: not valid UTF-8 text ({exc.reason})") from None


def _read_ledger(path: str) -> str:
    if path == "-":
        try:
            data = sys.stdin.buffer.read()
        except OSError as exc:
            raise _ReadError(f"<stdin>: {exc.strerror or exc}") from None
        return _decode(data, "<stdin>")
    try:
        with open(path, "rb") as fh:
            data = fh.read()
    except OSError as exc:
        raise _ReadError(f"{path}: {exc.strerror or exc}") from None
    return _decode(data, path)


def _sorted(entries: List[Entry]) -> List[Entry]:
    return sorted(entries, key=lambda e: e.date)  # stable: same-day keeps file order


def _entry_dict(e: Entry) -> dict:
    return {
        "date": e.date.isoformat(),
        "category": e.category,
        "amount": format_amount(e.amount),
        "note": e.note,
    }


def _out(lines: List[str]) -> None:
    sys.stdout.write("".join(line + "\n" for line in lines))


def _cmd_balance(args, entries):
    total = format_amount(balance(entries))
    _out([json.dumps({"balance": total})] if args.json else [total])


def _cmd_summary(args, entries):
    totals = by_month(entries) if args.by == "month" else by_category(entries)
    if args.json:
        _out([json.dumps({k: format_amount(v) for k, v in totals.items()}, ensure_ascii=False)])
    else:
        _out([f"{k}  {format_amount(v)}" for k, v in totals.items()])


def _cmd_list(args, entries):
    selected = _sorted(
        filter_entries(entries, category=args.category, since=args.since, until=args.until)
    )
    if args.json:
        _out([json.dumps([_entry_dict(e) for e in selected], ensure_ascii=False)])
    else:
        _out([format_entry(e) for e in selected])


def _cmd_export(args, entries):
    writer = csv.writer(sys.stdout, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in _sorted(entries):
        d = _entry_dict(e)
        writer.writerow([d["date"], d["category"], d["amount"], d["note"]])


def _cmd_add(args) -> int:
    path = args.file
    try:
        with open(path, "rb") as fh:
            existing = fh.read()
    except FileNotFoundError:
        existing = b""
    except OSError as exc:
        raise _ReadError(f"{path}: {exc.strerror or exc}") from None

    if existing:
        text = _decode(existing, path)
        lineno = len(text.split("\n")) + (0 if text.endswith("\n") else 1)
        if text.endswith("\n"):
            lineno -= 1
    else:
        lineno = 1

    fields = [args.date, args.category, args.amount]
    note = args.note.strip()
    try:
        for value, what in ((args.date, "date"), (args.category, "category"), (args.amount, "amount")):
            if not value or any(ch.isspace() for ch in value):
                raise ParseError(lineno, f"invalid {what} {value!r}")
        if any(ch in note for ch in "\r\n"):
            raise ParseError(lineno, "note must be on a single line")
        entry = parse_line(" ".join(fields + ([note] if note else [])), lineno)
        if entry is None:  # e.g. a date starting with '#'
            raise ParseError(lineno, f"invalid date {args.date!r}")
    except ParseError as exc:
        print(f"pennywise: invalid entry: {exc}", file=sys.stderr)
        return EXIT_LEDGER

    line = format_entry(entry)
    prefix = b"\n" if existing and not existing.endswith(b"\n") else b""
    try:
        with open(path, "ab") as fh:
            fh.write(prefix + (line + "\n").encode("utf-8"))
    except OSError as exc:
        raise _ReadError(f"{path}: {exc.strerror or exc}") from None
    _out([line])
    return EXIT_OK


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "export": _cmd_export,
}


def main(argv: Optional[List[str]] = None) -> int:
    parser = _build_parser()
    try:
        args = parser.parse_args(argv)
    except SystemExit as exc:
        return exc.code if isinstance(exc.code, int) else EXIT_USAGE

    try:
        if args.command == "add":
            return _cmd_add(args)
        try:
            entries = parse(_read_ledger(args.file))
        except ParseError as exc:
            print(f"pennywise: {args.file}: {exc}", file=sys.stderr)
            return EXIT_LEDGER
        _COMMANDS[args.command](args, entries)
        sys.stdout.flush()
    except _ReadError as exc:
        print(f"pennywise: {exc}", file=sys.stderr)
        return EXIT_USAGE
    except BrokenPipeError:
        devnull = os.open(os.devnull, os.O_WRONLY)
        os.dup2(devnull, sys.stdout.fileno())
        return EXIT_OK
    return EXIT_OK


if __name__ == "__main__":
    sys.exit(main())
